// Parser states.
const FIELD_START = 0; // at the first character of a field
const UNQUOTED = 1; // inside an unquoted field
const QUOTED = 2; // inside a quoted field
const QUOTE_SEEN = 3; // saw '"' inside a quoted field: escape or close
