      // Outside quotes: FIELD_START, UNQUOTED, or AFTER_QUOTE.
      if (c === '\n') {
        if (wasCR) continue; // LF of a CRLF; record already emitted at CR
        line++;
        endRecord(records);
      } else if (c === '\r') {
