'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function splits(text, opts) {
  const whole = parse(text, opts);
  for (let a = 0; a <= text.length; a++) {
    for (let b = a; b <= text.length; b++) {
      const p = createParser(opts);
      const out = [];
      for (const c of [text.slice(0, a), '', text.slice(a, b), text.slice(b)]) out.push(...p.push(c));
      out.push(...p.end());
      assert.deepEqual(out, whole, JSON.stringify([text, a, b]));
    }
  }
  return whole;
}
const eq = (t, e, o) => assert.deepEqual(splits(t, o), e, JSON.stringify(t));
eq('', []);
eq('\uFEFF', []);
eq('\n', [['']]);
eq('\n\n', [[''], ['']]);
eq('a\n', [['a']]);
eq('a\r\nb\rc\n\rd', [['a'], ['b'], ['c'], [''], ['d']]);
eq('\uFEFFa,\uFEFFb', [['a', '\uFEFFb']]);
eq('a"b,"c""d"\r\n', [['a"b', 'c"d']]);
eq('"x\r\ny\rz\n",""\n', [['x\r\ny\rz\n', '']]);
eq('a;b,c', [['a', 'b,c']], { delimiter: ';' });
eq('"a\tb"\t', [['a\tb', '']], { delimiter: '\t' });
eq('"",', [['', '']]);
eq('😀,"😀"', [['😀', '😀']]);

function err(text, n) {
  for (let a = 0; a <= text.length; a++) {
    const p = createParser();
    assert.throws(() => { p.push(text.slice(0, a)); p.push(text.slice(a)); p.end(); },
      e => e instanceof SyntaxError && e.message.includes(`line ${n}`), JSON.stringify([text, a]));
  }
}
err('"a" ,b', 1);
err('x\r\n"a\r\nb"c', 3);
err('x\r\n"a\r\nb\rc\nd', 5);
err('"abc', 1);

// immediate emission at CR
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
assert.throws(() => createParser().push(1), TypeError);
for (const d of ['', ',,', '"', '\r', '\n', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
assert.deepEqual(createParser({ delimiter: undefined }).push('a,b\n'), [['a', 'b']]);
assert.deepEqual(parse('', { header: true }), []);
const objs = parse('x,x,x_2,__proto__\n1,2\n', { header: true });
assert.deepEqual(Object.keys(objs[0]), ['x', 'x_2', 'x_2_2', '__proto__']);
assert.equal(objs[0].__proto__, '');
assert.equal(Object.getPrototypeOf(objs[0]), Object.prototype);
console.log('smoke ok');

